
const IMG_VERDE = 'data:image/png;base64,';
const IMG_BRANCO = 'data:image/png;base64,';

// ─── ESTADO ────────────────────────────────────────────────────────────────────
let listaGrupos = JSON.parse(localStorage.getItem('grupos')) || [];
let listaInsetos = JSON.parse(localStorage.getItem('insetos')) || [];
let insetoAtual = null;
let caminho = []; // pilha de grupos abertos (ordem -> família)
let imagensGaleriaAtual = [];
let indiceImagemAtual = 0;
let buscaAtual = '';

// Migração: grupos antigos sem tipo viram 'ordem'
let precisaSalvarGrupos = false;
listaGrupos.forEach(g => { if (!g.tipo) { g.tipo = 'ordem'; precisaSalvarGrupos = true; } });
if (precisaSalvarGrupos) localStorage.setItem('grupos', JSON.stringify(listaGrupos));

const MAX_GALERIA = 20;

// ─── HELPERS ──────────────────────────────────────────────────────────────────
function grupoAtual() { return caminho.length ? caminho[caminho.length-1] : null; }
function grupoPorId(id) { return listaGrupos.find(g => g.id === id); }
function ordensAll() { return listaGrupos.filter(g => g.tipo === 'ordem'); }
function familiasDe(ordemId) { return listaGrupos.filter(g => g.tipo === 'familia' && g.paiId === ordemId); }
function insetosDe(familiaId) { return listaInsetos.filter(i => i.grupoId === familiaId); }
function insetosSemGrupo() { return listaInsetos.filter(i => !i.grupoId || !grupoPorId(i.grupoId)); }
function ordemDoInseto(inseto) {
    const fam = inseto.grupoId ? grupoPorId(inseto.grupoId) : null;
    if (!fam) return null;
    return fam.paiId ? grupoPorId(fam.paiId) : null;
}
function familiaDoInseto(inseto) { return inseto.grupoId ? grupoPorId(inseto.grupoId) : null; }

function salvarGrupos() { localStorage.setItem('grupos', JSON.stringify(listaGrupos)); }
function salvarInsetos() { localStorage.setItem('insetos', JSON.stringify(listaInsetos)); }

function mostrarToast(msg) {
    const toast = document.getElementById('toastMsg');
    toast.textContent = msg;
    toast.classList.add('visivel');
    clearTimeout(toast._t);
    toast._t = setTimeout(() => toast.classList.remove('visivel'), 2600);
}

// ─── DRAG & DROP ──────────────────────────────────────────────────────────────
let arrasto = null; // { tipo:'inseto'|'familia', id }

function iniciarDrag(e, tipo, id) {
    arrasto = { tipo, id };
    e.dataTransfer.effectAllowed = 'move';
    try { e.dataTransfer.setData('text/plain', id); } catch(_) {}
    setTimeout(() => {
        const sel = tipo === 'inseto' ? `[data-id="${id}"]` : `[data-grupo-id="${id}"]`;
        document.querySelectorAll(sel).forEach(c => c.classList.add('arrastando'));
    }, 0);
}
function finalizarDrag() {
    document.querySelectorAll('.arrastando').forEach(c => c.classList.remove('arrastando'));
    document.querySelectorAll('.grupo-alvo').forEach(c => c.classList.remove('grupo-alvo'));
    arrasto = null;
}
function dragEnterGrupo(e, grupoId) {
    e.preventDefault();
    if (!arrasto) return;
    const grupo = grupoPorId(grupoId);
    if (!grupo) return;
    // Validar compatibilidade
    if (arrasto.tipo === 'familia' && grupo.tipo !== 'ordem') return;
    if (arrasto.tipo === 'inseto' && grupo.tipo !== 'familia') return;
    const card = document.querySelector(`[data-grupo-id="${grupoId}"]`);
    if (card) card.classList.add('grupo-alvo');
}
function dragLeaveGrupo(e, grupoId) {
    const card = document.querySelector(`[data-grupo-id="${grupoId}"]`);
    if (card) card.classList.remove('grupo-alvo');
}
function dragOverGrupo(e) { e.preventDefault(); if (e.dataTransfer) e.dataTransfer.dropEffect = 'move'; }
function dropNoGrupo(e, grupoId) {
    e.preventDefault();
    e.stopPropagation();
    const card = document.querySelector(`[data-grupo-id="${grupoId}"]`);
    if (card) card.classList.remove('grupo-alvo');
    if (!arrasto) return;
    const destino = grupoPorId(grupoId);
    if (!destino) return;
    if (arrasto.tipo === 'familia' && destino.tipo === 'ordem') {
        const fam = grupoPorId(arrasto.id);
        if (fam && fam.paiId !== destino.id) {
            fam.paiId = destino.id;
            salvarGrupos();
            mostrarToast(`Família "${fam.nome}" movida para "${destino.nome}"`);
            renderizar();
        }
    } else if (arrasto.tipo === 'inseto' && destino.tipo === 'familia') {
        const ins = listaInsetos.find(i => i.id === arrasto.id);
        if (ins && ins.grupoId !== destino.id) {
            ins.grupoId = destino.id;
            salvarInsetos();
            mostrarToast(`"${ins.nomePopular}" movido para "${destino.nome}"`);
            renderizar();
        }
    }
}

// ─── NAVEGAÇÃO ────────────────────────────────────────────────────────────────
function voltarParaHome() {
    caminho = [];
    insetoAtual = null;
    document.getElementById('telaDetalhes').style.display = 'none';
    document.getElementById('telaPrincipal').style.display = 'block';
    document.getElementById('acoesGrupo').style.display = 'none';
    document.getElementById('campoBusca').value = '';
    buscaAtual = '';
    renderizar();
    window.scrollTo({ top: 0, behavior: 'smooth' });
}

function abrirGrupo(id) {
    const g = grupoPorId(id);
    if (!g) return;
    // Construir caminho desde a raiz
    caminho = [];
    let cur = g;
    while (cur) {
        caminho.unshift(cur);
        cur = cur.paiId ? grupoPorId(cur.paiId) : null;
    }
    insetoAtual = null;
    document.getElementById('telaDetalhes').style.display = 'none';
    document.getElementById('telaPrincipal').style.display = 'block';
    document.getElementById('acoesGrupo').style.display = 'flex';
    document.getElementById('campoBusca').value = '';
    buscaAtual = '';
    renderizar();
    window.scrollTo({ top: 0, behavior: 'smooth' });
}

function irParaCrumb(index) {
    if (index < 0) return voltarParaHome();
    caminho = caminho.slice(0, index + 1);
    insetoAtual = null;
    document.getElementById('telaDetalhes').style.display = 'none';
    document.getElementById('telaPrincipal').style.display = 'block';
    document.getElementById('acoesGrupo').style.display = caminho.length ? 'flex' : 'none';
    document.getElementById('campoBusca').value = '';
    buscaAtual = '';
    renderizar();
}

function renderizarCrumbs() {
    const c = document.getElementById('crumbs');
    let html = `<span data-nav="home">Início</span>`;
    caminho.forEach((g, i) => {
        html += ` <span style="color:#999">/</span> <span data-nav="${i}">${escapeHtml(g.nome)}</span>`;
    });
    c.innerHTML = html;
    c.querySelectorAll('span[data-nav]').forEach(el => {
        el.addEventListener('click', () => {
            const v = el.getAttribute('data-nav');
            if (v === 'home') voltarParaHome();
            else irParaCrumb(parseInt(v, 10));
        });
    });
}

function escapeHtml(s) {
    return (s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

// ─── MENU ─────────────────────────────────────────────────────────────────────
document.getElementById('botaoCriar').addEventListener('click', () => {
    const menu = document.getElementById('menuOpcoes');
    const g = grupoAtual();
    // Habilita/desabilita conforme contexto
    document.getElementById('btnNovaOrdem').disabled = !!g; // só na raiz
    document.getElementById('btnNovaFamilia').disabled = !(g && g.tipo === 'ordem');
    document.getElementById('btnNovoInseto').disabled = !(g && g.tipo === 'familia');
    menu.style.display = menu.style.display === 'flex' ? 'none' : 'flex';
});

document.addEventListener('click', (e) => {
    const menu = document.getElementById('menuOpcoes');
    if (!menu.contains(e.target) && e.target.id !== 'botaoCriar') menu.style.display = 'none';
});

// ─── BUSCA ────────────────────────────────────────────────────────────────────
document.getElementById('campoBusca').addEventListener('input', function() {
    buscaAtual = this.value.trim().toLowerCase();
    renderizar();
});

function matchTexto(...campos) {
    if (!buscaAtual) return true;
    return campos.some(c => (c || '').toString().toLowerCase().includes(buscaAtual));
}

// ─── MODAIS ───────────────────────────────────────────────────────────────────
function abrirModalGrupo(tipo) {
    const g = grupoAtual();
    if (tipo === 'ordem' && g) { mostrarToast('Volte ao início para criar uma Ordem'); return; }
    if (tipo === 'familia' && (!g || g.tipo !== 'ordem')) { mostrarToast('Abra uma Ordem para criar uma Família'); return; }
    document.getElementById('formGrupo').reset();
    document.getElementById('idEdicaoGrupo').value = '';
    document.getElementById('tipoGrupo').value = tipo;
    document.getElementById('paiGrupo').value = tipo === 'familia' ? g.id : '';
    document.getElementById('tituloModalGrupo').textContent = tipo === 'ordem' ? 'Nova Ordem' : `Nova Família em "${g.nome}"`;
    document.getElementById('modalGrupo').style.display = 'flex';
    document.getElementById('menuOpcoes').style.display = 'none';
}
function abrirModalEditarGrupo() {
    const g = grupoAtual();
    if (!g) return;
    document.getElementById('idEdicaoGrupo').value = g.id;
    document.getElementById('tipoGrupo').value = g.tipo;
    document.getElementById('paiGrupo').value = g.paiId || '';
    document.getElementById('nomeGrupo').value = g.nome;
    document.getElementById('descricaoGrupo').value = g.descricao || '';
    document.getElementById('tituloModalGrupo').textContent = g.tipo === 'ordem' ? 'Editar Ordem' : 'Editar Família';
    document.getElementById('modalGrupo').style.display = 'flex';
}
function abrirModalArquivo() {
    const g = grupoAtual();
    if (!g || g.tipo !== 'familia') { mostrarToast('Abra uma Família para cadastrar um inseto'); return; }
    document.getElementById('tituloModalArquivo').textContent = 'Cadastrar Novo Inseto';
    document.getElementById('formArquivo').reset();
    document.getElementById('idEdicao').value = '';
    document.getElementById('grupoPertencente').value = g.id;
    document.getElementById('bannerPreview').style.display = 'none';
    document.getElementById('bannerPreview').src = '';
    document.getElementById('galeriaPreviews').innerHTML = '';
    imagensGaleriaAtual = [];
    preencherFamiliaSelect(g.id);
    document.getElementById('modalArquivo').style.display = 'flex';
    document.getElementById('menuOpcoes').style.display = 'none';
}
function preencherFamiliaSelect(selecionadoId) {
    const sel = document.getElementById('familiaSelect');
    const familias = listaGrupos.filter(g => g.tipo === 'familia');
    if (familias.length === 0) {
        sel.innerHTML = '<option value="">— nenhuma família cadastrada —</option>';
        return;
    }
    sel.innerHTML = familias.map(f => {
        const ord = f.paiId ? grupoPorId(f.paiId) : null;
        return `<option value="${f.id}" ${f.id===selecionadoId?'selected':''}>${escapeHtml(f.nome)}${ord?` — ${escapeHtml(ord.nome)}`:''}</option>`;
    }).join('');
}
function fecharModal() {
    document.querySelectorAll('.modal').forEach(m => m.style.display = 'none');
    document.getElementById('menuOpcoes').style.display = 'none';
}

// ─── IMAGENS ──────────────────────────────────────────────────────────────────
function lerArquivoComoBase64(arquivo) {
    return new Promise((resolve) => {
        if (!arquivo) return resolve('');
        const r = new FileReader();
        r.onloadend = () => resolve(r.result);
        r.readAsDataURL(arquivo);
    });
}

document.getElementById('bannerInput').addEventListener('change', function() {
    const f = this.files && this.files[0];
    if (!f) return;
    lerArquivoComoBase64(f).then(d => {
        const p = document.getElementById('bannerPreview');
        p.src = d;
        p.style.display = 'block';
    });
});

document.getElementById('galeriaInput').addEventListener('change', async function() {
    if (!this.files) return;
    const restante = MAX_GALERIA - imagensGaleriaAtual.length;
    if (restante <= 0) { mostrarToast(`Limite de ${MAX_GALERIA} fotos atingido`); return; }
    const arquivos = Array.from(this.files).slice(0, restante);
    if (this.files.length > restante) mostrarToast(`Foram adicionadas apenas ${restante} fotos (limite ${MAX_GALERIA})`);
    for (const f of arquivos) {
        const d = await lerArquivoComoBase64(f);
        imagensGaleriaAtual.push(d);
    }
    this.value = '';
    renderizarGaleriaPreview();
});

function renderizarGaleriaPreview() {
    const c = document.getElementById('galeriaPreviews');
    c.innerHTML = '';
    imagensGaleriaAtual.forEach((src, idx) => {
        const wrap = document.createElement('div');
        wrap.style.position = 'relative';
        const img = document.createElement('img');
        img.src = src; img.className = 'galeria-previews-thumb';
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.textContent = '×';
        btn.title = 'Remover';
        btn.style.cssText = 'position:absolute;top:-6px;right:-6px;width:22px;height:22px;border-radius:50%;border:none;background:#c0392b;color:white;cursor:pointer;font-weight:bold;';
        btn.onclick = () => { imagensGaleriaAtual.splice(idx, 1); renderizarGaleriaPreview(); };
        wrap.appendChild(img); wrap.appendChild(btn);
        c.appendChild(wrap);
    });
}

function abrirVisualizacaoImagem(src, indice = 0, galeria = null) {
    const modal = document.getElementById('modalImagem');
    const img = document.getElementById('imagemVisualizada');
    if (galeria && galeria.length > 1) {
        imagensGaleriaAtual = galeria;
        indiceImagemAtual = indice;
        document.getElementById('btnAnterior').style.display = 'flex';
        document.getElementById('btnProxima').style.display = 'flex';
    } else {
        imagensGaleriaAtual = [src];
        indiceImagemAtual = 0;
        document.getElementById('btnAnterior').style.display = 'none';
        document.getElementById('btnProxima').style.display = 'none';
    }
    img.src = src;
    modal.style.display = 'flex';
}
function fecharVisualizacaoImagem() { document.getElementById('modalImagem').style.display = 'none'; }
function imagemAnterior() { indiceImagemAtual = (indiceImagemAtual - 1 + imagensGaleriaAtual.length) % imagensGaleriaAtual.length; document.getElementById('imagemVisualizada').src = imagensGaleriaAtual[indiceImagemAtual]; }
function imagemProxima() { indiceImagemAtual = (indiceImagemAtual + 1) % imagensGaleriaAtual.length; document.getElementById('imagemVisualizada').src = imagensGaleriaAtual[indiceImagemAtual]; }

// ─── DETALHES ─────────────────────────────────────────────────────────────────
function abrirDetalhes(id) {
    insetoAtual = listaInsetos.find(i => i.id === id);
    if (!insetoAtual) return;
    const banner = document.getElementById('viewBanner');
    if (insetoAtual.banner) { banner.src = insetoAtual.banner; }
    else { banner.src = IMG_VERDE; }

    document.getElementById('viewNomeCientifico').textContent = insetoAtual.nomeCientifico || '';
    const ord = ordemDoInseto(insetoAtual);
    const fam = familiaDoInseto(insetoAtual);
    const subt = [insetoAtual.nomePopular, ord && ord.nome, fam && fam.nome].filter(Boolean).join(' · ');
    document.getElementById('viewNomePopular').textContent = subt;
    document.getElementById('viewTempoVida').textContent = insetoAtual.tempoVida || '—';
    document.getElementById('viewAdaptacoes').textContent = insetoAtual.adaptacoes || '—';
    document.getElementById('viewTamanhoPeso').textContent = insetoAtual.tamanhoPeso || '—';
    document.getElementById('viewHabitat').textContent = insetoAtual.habitat || '—';
    document.getElementById('viewRegiao').textContent = insetoAtual.regiao || '—';
    document.getElementById('viewAlimentacao').textContent = insetoAtual.alimentacao || '—';
    const historia = (insetoAtual.historia || '').trim();
    document.getElementById('viewHistoria').textContent = historia || 'Sem informações registradas ainda.';

    const galeria = document.getElementById('viewGaleria');
    galeria.innerHTML = '';
    (insetoAtual.galeria || []).forEach((imgSrc, idx) => {
        const img = document.createElement('img');
        img.src = imgSrc;
        img.alt = insetoAtual.nomePopular || '';
        img.onclick = () => abrirVisualizacaoImagem(imgSrc, idx, insetoAtual.galeria);
        galeria.appendChild(img);
    });

    document.getElementById('telaPrincipal').style.display = 'none';
    document.getElementById('telaDetalhes').style.display = 'block';
    document.getElementById('acoesGrupo').style.display = 'none';
    window.scrollTo({ top: 0, behavior: 'smooth' });
}

function abrirModalEdicao() {
    if (!insetoAtual) return;
    document.getElementById('tituloModalArquivo').textContent = 'Editar Inseto';
    document.getElementById('idEdicao').value = insetoAtual.id;
    document.getElementById('grupoPertencente').value = insetoAtual.grupoId || '';
    preencherFamiliaSelect(insetoAtual.grupoId);
    document.getElementById('nomeCientifico').value = insetoAtual.nomeCientifico || '';
    document.getElementById('nomePopular').value = insetoAtual.nomePopular || '';
    document.getElementById('tempoVida').value = insetoAtual.tempoVida || '';
    document.getElementById('adaptacoes').value = insetoAtual.adaptacoes || '';
    document.getElementById('tamanhoPeso').value = insetoAtual.tamanhoPeso || '';
    document.getElementById('habitat').value = insetoAtual.habitat || '';
    document.getElementById('regiao').value = insetoAtual.regiao || '';
    document.getElementById('alimentacao').value = insetoAtual.alimentacao || '';
    document.getElementById('historia').value = insetoAtual.historia || '';
    const bp = document.getElementById('bannerPreview');
    if (insetoAtual.banner) { bp.src = insetoAtual.banner; bp.style.display = 'block'; }
    else { bp.style.display = 'none'; }
    imagensGaleriaAtual = (insetoAtual.galeria || []).slice();
    renderizarGaleriaPreview();
    document.getElementById('modalArquivo').style.display = 'flex';
}

function confirmarExclusao() {
    if (!insetoAtual) return;
    if (confirm('Tem certeza que deseja excluir este inseto?')) {
        listaInsetos = listaInsetos.filter(i => i.id !== insetoAtual.id);
        salvarInsetos();
        voltarParaHome();
    }
}
function confirmarExclusaoGrupo() {
    const g = grupoAtual();
    if (!g) return;
    const aviso = g.tipo === 'ordem'
        ? 'Tem certeza que deseja excluir esta Ordem? TODAS as famílias dentro dela e seus insetos serão excluídos!'
        : 'Tem certeza que deseja excluir esta Família? TODOS os insetos dentro dela serão excluídos!';
    if (!confirm(aviso)) return;
    if (g.tipo === 'ordem') {
        const familias = familiasDe(g.id).map(f => f.id);
        listaInsetos = listaInsetos.filter(i => !familias.includes(i.grupoId));
        listaGrupos = listaGrupos.filter(x => x.id !== g.id && !familias.includes(x.id));
    } else {
        listaInsetos = listaInsetos.filter(i => i.grupoId !== g.id);
        listaGrupos = listaGrupos.filter(x => x.id !== g.id);
    }
    salvarInsetos(); salvarGrupos();
    // sair do nível excluído
    caminho.pop();
    if (caminho.length === 0) voltarParaHome();
    else { document.getElementById('acoesGrupo').style.display = 'flex'; renderizar(); }
}

// ─── MOVER (modal) ────────────────────────────────────────────────────────────
function abrirModalMoverGrupo() {
    if (!insetoAtual) return;
    const lista = document.getElementById('listaGruposMover');
    document.getElementById('tituloModalMover').textContent = 'Mover para Família';
    lista.innerHTML = '';
    const familias = listaGrupos.filter(g => g.tipo === 'familia');
    if (familias.length === 0) {
        lista.innerHTML = '<p style="color:#888;text-align:center;padding:20px;">Nenhuma família cadastrada ainda.</p>';
    } else {
        familias.forEach(f => {
            if (f.id === insetoAtual.grupoId) return;
            const ord = f.paiId ? grupoPorId(f.paiId) : null;
            const btn = document.createElement('button');
            btn.className = 'btn-grupo-mover';
            btn.innerHTML = `📁 <span><strong>${escapeHtml(f.nome)}</strong>${ord?` <small>(${escapeHtml(ord.nome)})</small>`:''}</span>`;
            btn.onclick = () => {
                insetoAtual.grupoId = f.id;
                salvarInsetos();
                mostrarToast(`"${insetoAtual.nomePopular}" movido para "${f.nome}"`);
                fecharModal();
                abrirDetalhes(insetoAtual.id);
            };
            lista.appendChild(btn);
        });
    }
    document.getElementById('modalMoverGrupo').style.display = 'flex';
}

// ─── CARDS ────────────────────────────────────────────────────────────────────
function cardOrdem(grupo) {
    const card = document.createElement('div');
    card.className = 'card';
    card.setAttribute('data-grupo-id', grupo.id);
    card.onclick = () => abrirGrupo(grupo.id);
    card.addEventListener('dragenter', (e) => dragEnterGrupo(e, grupo.id));
    card.addEventListener('dragleave', (e) => dragLeaveGrupo(e, grupo.id));
    card.addEventListener('dragover', dragOverGrupo);
    card.addEventListener('drop', (e) => dropNoGrupo(e, grupo.id));
    const qtdFam = familiasDe(grupo.id).length;
    const qtdIns = familiasDe(grupo.id).reduce((acc,f)=>acc+insetosDe(f.id).length, 0);
    card.innerHTML = `
        <div class="tipo-tag">ORDEM</div>
        <div class="card-banner-grupo"><img src="${IMG_BRANCO}" alt=""></div>
        <div class="card-info">
            <h3>${escapeHtml(grupo.nome)}</h3>
            <p>${escapeHtml(grupo.descricao || 'Ordem')} · ${qtdFam} família${qtdFam!==1?'s':''} · ${qtdIns} inseto${qtdIns!==1?'s':''}</p>
        </div>`;
    return card;
}
function cardFamilia(grupo, draggable=true) {
    const card = document.createElement('div');
    card.className = 'card';
    card.setAttribute('data-grupo-id', grupo.id);
    card.onclick = () => abrirGrupo(grupo.id);
    if (draggable) {
        card.draggable = true;
        card.addEventListener('dragstart', (e) => iniciarDrag(e, 'familia', grupo.id));
        card.addEventListener('dragend', finalizarDrag);
    }
    card.addEventListener('dragenter', (e) => dragEnterGrupo(e, grupo.id));
    card.addEventListener('dragleave', (e) => dragLeaveGrupo(e, grupo.id));
    card.addEventListener('dragover', dragOverGrupo);
    card.addEventListener('drop', (e) => dropNoGrupo(e, grupo.id));
    const qtd = insetosDe(grupo.id).length;
    const ord = grupo.paiId ? grupoPorId(grupo.paiId) : null;
    card.innerHTML = `
        ${draggable ? '<div class="drag-handle">arrastar</div>' : ''}
        <div class="tipo-tag">FAMÍLIA</div>
        <div class="card-banner-grupo familia"><img src="${IMG_BRANCO}" alt=""></div>
        <div class="card-info">
            <h3>${escapeHtml(grupo.nome)}</h3>
            <p>${ord ? escapeHtml(ord.nome) + ' · ' : ''}${qtd} inseto${qtd!==1?'s':''}</p>
        </div>`;
    return card;
}
function cardInseto(inseto, draggable=true) {
    const card = document.createElement('div');
    card.className = 'card';
    card.setAttribute('data-id', inseto.id);
    card.onclick = () => abrirDetalhes(inseto.id);
    if (draggable) {
        card.draggable = true;
        card.addEventListener('dragstart', (e) => iniciarDrag(e, 'inseto', inseto.id));
        card.addEventListener('dragend', finalizarDrag);
    }
    let bannerHTML;
    if (inseto.banner) bannerHTML = `<img class="card-banner-img" src="${inseto.banner}" alt="">`;
    else bannerHTML = `<div class="card-banner-inseto-icone"><img src="${IMG_VERDE}" alt=""></div>`;
    const ord = ordemDoInseto(inseto);
    const fam = familiaDoInseto(inseto);
    const meta = [fam && fam.nome, ord && ord.nome].filter(Boolean).join(' · ') || 'Sem classificação';
    card.innerHTML = `
        ${draggable ? '<div class="drag-handle">arrastar</div>' : ''}
        <div class="tipo-tag" style="background:#CFE84A;color:#2d4d12;">INSETO</div>
        ${bannerHTML}
        <div class="card-info">
            <h3>${escapeHtml(inseto.nomePopular || inseto.nomeCientifico || 'Sem nome')}</h3>
            <p>${escapeHtml(meta)}</p>
        </div>`;
    return card;
}

// ─── RENDER PRINCIPAL ─────────────────────────────────────────────────────────
function renderizar() {
    renderizarCrumbs();
    const grid = document.getElementById('gridPrincipal');
    grid.innerHTML = '';
    const g = grupoAtual();
    const dica = document.getElementById('dicaDrag');

    let itens = [];
    if (!g) {
        // Home: ordens + insetos sem família
        const ordens = ordensAll().filter(o => matchTexto(o.nome, o.descricao));
        const livres = insetosSemGrupo().filter(i => matchTexto(i.nomePopular, i.nomeCientifico));
        ordens.forEach(o => itens.push(cardOrdem(o)));
        livres.forEach(i => itens.push(cardInseto(i, true)));
        dica.style.display = (ordens.length > 0 && livres.length > 0) ? 'block' : 'none';
        if (itens.length === 0) {
            grid.innerHTML = `<p class="aviso-vazio">ainda não há nenhum inseto cadastrado :(</p>`;
            return;
        }
    } else if (g.tipo === 'ordem') {
        // Mostra famílias da ordem
        const fams = familiasDe(g.id).filter(f => matchTexto(f.nome, f.descricao));
        fams.forEach(f => itens.push(cardFamilia(f, true)));
        dica.style.display = fams.length > 0 ? 'block' : 'none';
        if (itens.length === 0) {
            grid.innerHTML = `<p class="aviso-vazio">ainda não há nenhuma família cadastrada nesta ordem :(</p>`;
            return;
        }
    } else {
        // Família: mostra insetos
        const ins = insetosDe(g.id).filter(i => matchTexto(i.nomePopular, i.nomeCientifico));
        ins.forEach(i => itens.push(cardInseto(i, true)));
        dica.style.display = 'none';
        if (itens.length === 0) {
            grid.innerHTML = `<p class="aviso-vazio">ainda não há nenhum inseto cadastrado :(</p>`;
            return;
        }
    }

    itens.forEach(c => grid.appendChild(c));
}

// ─── FORM GRUPO ───────────────────────────────────────────────────────────────
document.getElementById('formGrupo').addEventListener('submit', function(e) {
    e.preventDefault();
    const id = document.getElementById('idEdicaoGrupo').value;
    const tipo = document.getElementById('tipoGrupo').value;
    const paiId = document.getElementById('paiGrupo').value || null;
    const nome = document.getElementById('nomeGrupo').value.trim();
    const descricao = document.getElementById('descricaoGrupo').value.trim();
    if (id) {
        const g = grupoPorId(id);
        if (g) { g.nome = nome; g.descricao = descricao; }
    } else {
        listaGrupos.push({ id: Date.now().toString(), tipo, paiId, nome, descricao });
    }
    salvarGrupos();
    fecharModal();
    renderizar();
});

// ─── FORM INSETO ──────────────────────────────────────────────────────────────
document.getElementById('formArquivo').addEventListener('submit', async function(e) {
    e.preventDefault();
    const id = document.getElementById('idEdicao').value;
    const familiaId = document.getElementById('familiaSelect').value;
    if (!familiaId) { mostrarToast('Selecione ou crie uma família primeiro'); return; }
    const dados = {
        id: id || Date.now().toString(),
        grupoId: familiaId,
        nomeCientifico: document.getElementById('nomeCientifico').value.trim(),
        nomePopular: document.getElementById('nomePopular').value.trim(),
        tempoVida: document.getElementById('tempoVida').value.trim(),
        adaptacoes: document.getElementById('adaptacoes').value.trim(),
        tamanhoPeso: document.getElementById('tamanhoPeso').value.trim(),
        habitat: document.getElementById('habitat').value.trim(),
        regiao: document.getElementById('regiao').value.trim(),
        alimentacao: document.getElementById('alimentacao').value.trim(),
        historia: document.getElementById('historia').value.trim(),
        banner: '',
        galeria: imagensGaleriaAtual.slice(0, MAX_GALERIA)
    };
    const bannerFile = document.getElementById('bannerInput').files[0];
    if (bannerFile) dados.banner = await lerArquivoComoBase64(bannerFile);
    else if (id) {
        const ant = listaInsetos.find(i => i.id === id);
        if (ant) dados.banner = ant.banner || '';
    }
    if (id) {
        const idx = listaInsetos.findIndex(i => i.id === id);
        if (idx !== -1) listaInsetos[idx] = dados;
    } else {
        listaInsetos.push(dados);
    }
    salvarInsetos();
    fecharModal();
    if (insetoAtual && insetoAtual.id === dados.id) { insetoAtual = dados; abrirDetalhes(dados.id); }
    else renderizar();
});

// ─── INIT ─────────────────────────────────────────────────────────────────────
renderizar();
